package com.maikal.daily;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

public class TrackActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private LinearLayout root;private int range=0,generation=0;private boolean active=false;
    private final Runnable tick=new Runnable(){public void run(){if(active){load();handler.postDelayed(this,60000);}}};
    private boolean localOnly(){return getPackageName().endsWith(".local");}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(6),0,dp(6));return t;}
    private TextView heading(String s,int size){TextView t=text(s,size,0xff253439);t.setTypeface(Typeface.create("serif",Typeface.NORMAL));return t;}
    private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private Button button(String label,LinearLayout parent,Runnable action){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextColor(0xff25704d);b.setBackgroundColor(Color.TRANSPARENT);parent.addView(b);b.setOnClickListener(v->action.run());return b;}
    private void page(){FrameLayout frame=new FrameLayout(this);frame.setBackgroundColor(0xffffffff);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(12),dp(22),dp(32));scroll.addView(root);frame.addView(scroll);frame.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(frame);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);root.addView(bar);button("‹ Back",bar,this::finish);TextView brand=heading("Maikal",18);brand.setGravity(Gravity.CENTER);bar.addView(brand,new LinearLayout.LayoutParams(0,-2,1));button("↻",bar,this::load).setContentDescription("Refresh usage");root.addView(heading("Track",34));LocalDate now=LocalDate.now();root.addView(text(range==2?"Last 7 days · "+now.minusDays(6)+" – "+now:(range==1?"Yesterday · ":"Today · ")+now.minusDays(range==1?1:0).format(DateTimeFormatter.ofPattern("EEE, d MMM",Locale.getDefault())),12,0xff72756e));}
    @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null)range=state.getInt("range",0);}
    @Override protected void onSaveInstanceState(Bundle state){state.putInt("range",range);super.onSaveInstanceState(state);}
    @Override protected void onResume(){super.onResume();active=true;load();handler.postDelayed(tick,60000);TrackWidgetProvider.refresh(this);}
    @Override protected void onPause(){active=false;generation++;handler.removeCallbacks(tick);super.onPause();}
    @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
    private void permission(){page();root.addView(text("A one-time setup",12,0xff72756e));root.addView(heading("See where your time goes.",28));root.addView(text("Allow Maikal to read app usage so you can see screen time and the apps you use most.",15,0xff536159));root.addView(text("1. Open Android’s Usage access settings.\n2. Select Maikal.\n3. Turn on Allow usage access.",14,0xff536159));button("Open usage access settings",root,()->{try{startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS,Uri.parse("package:"+getPackageName())));}catch(Exception e){startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS));}});root.addView(text(localOnly()?"Maikal reads app names and usage duration, not messages or activity inside apps. All usage data and daily totals stay on this device.":"Maikal reads app names and usage duration, not messages or activity inside apps. App-by-app data stays on this device. Only daily totals sync when you connect Firebase.",12,0xff72756e));}
    void load(){int request=++generation;if(!ScreenTime.allowed(this)){permission();return;}page();TextView loading=text("Reading device usage…",14,0xff72756e);root.addView(loading);int selectedRange=range;worker.execute(()->{try{ScreenTime.Result result=ScreenTime.read(this,selectedRange);runOnUiThread(()->{if(active&&request==generation)show(result);});}catch(Exception e){runOnUiThread(()->{if(active&&request==generation){if(!ScreenTime.allowed(this))permission();else{page();root.addView(text("Usage history is unavailable. Unlock your phone and try again.",15,0xffae5360));button("Try again",root,this::load);}}});}});}
    private void show(ScreenTime.Result result){page();LinearLayout filters=new LinearLayout(this);filters.setPadding(dp(3),dp(3),dp(3),dp(3));filters.setBackground(bg(0xffeae8de,7));root.addView(filters);String[] labels={"Today","Yesterday","7 days"};for(int i=0;i<3;i++){final int value=i;Button b=new Button(this);b.setAllCaps(false);b.setText(labels[i]);b.setTextSize(12);b.setTextColor(i==range?0xff25704d:0xff536159);b.setBackground(bg(i==range?0xffffffff:Color.TRANSPARENT,5));filters.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setOnClickListener(v->{range=value;load();});}root.addView(text(range==2?"Screen time over 7 days":"Total screen time",12,0xff536159));TextView total=heading(ScreenTime.duration(result.total),48);total.setTextColor(0xff25704d);total.setContentDescription("Total screen time "+ScreenTime.duration(result.total));root.addView(total);if(range==2)root.addView(text("Daily average · "+ScreenTime.duration(result.total/7),12,0xff44725c));root.addView(new UsageChart(result.buckets),new LinearLayout.LayoutParams(-1,dp(105)));root.addView(text(range==2?"Daily usage · oldest to newest":"00:00                  06:00                  12:00                  18:00",10,0xff72756e));root.addView(heading("Apps used",23));root.addView(text("Most used first · tap an app for details",11,0xff72756e));
        for(Map.Entry<String,Long> app:ScreenTime.sorted(result)){String name=ScreenTime.label(this,app.getKey());LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(12),0,dp(12));ImageView icon=new ImageView(this);try{icon.setImageDrawable(getPackageManager().getApplicationIcon(app.getKey()));}catch(Exception ignored){icon.setImageDrawable(getDrawable(android.R.drawable.sym_def_app_icon));}row.addView(icon,new LinearLayout.LayoutParams(dp(36),dp(36)));LinearLayout middle=new LinearLayout(this);middle.setOrientation(1);middle.setPadding(dp(12),0,dp(12),0);middle.addView(text(name,14,0xff253439));ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setProgress((int)(app.getValue()*1000/Math.max(1,ScreenTime.sorted(result).get(0).getValue())));progress.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff9ab1b6));middle.addView(progress,new LinearLayout.LayoutParams(-1,dp(4)));row.addView(middle,new LinearLayout.LayoutParams(0,-2,1));row.addView(text(ScreenTime.duration(app.getValue()),13,0xff253439));row.setFocusable(true);row.setContentDescription(name+", "+ScreenTime.duration(app.getValue()));row.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(name).setMessage(ScreenTime.duration(app.getValue())+"\n\nTime with this app on screen during the selected period.").setPositiveButton("Done",null).show());root.addView(row);}
        if(result.apps.isEmpty())root.addView(text("No app usage available for this period.",16,0xff72756e));root.addView(text("Time in foreground apps. Home, lock screen and background activity are excluded. Android may retain only a few days of detailed history. Split-screen apps can overlap; the total counts that time once.",11,0xff72756e));root.addView(text(localOnly()?"App usage and daily totals stay on this phone.":"App usage stays on this phone. Daily totals sync to your connected Firebase diary when Maikal is open or resumed.",11,0xff72756e));button("Usage access settings",root,()->startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)));}
    private class UsageChart extends View {final long[] values;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);UsageChart(long[] values){super(TrackActivity.this);this.values=values;setContentDescription("Screen-time usage chart");}protected void onDraw(Canvas canvas){super.onDraw(canvas);long max=1;for(long v:values)max=Math.max(max,v);float step=getWidth()/(float)Math.max(1,values.length);paint.setColor(0xff9ab1b6);for(int i=0;i<values.length;i++){float height=(getHeight()-dp(12))*values[i]/(float)max;canvas.drawRoundRect(i*step+dp(3),getHeight()-height,(i+1)*step-dp(3),getHeight(),dp(3),dp(3),paint);}}}
}
